push.css:
.fxs .au{--pr:26px;--pushA:#CC9636;--pushB:#5E3E0A;--pushC:#FFFFFF;--rim:#FCE3A0;--rimD:#5A3A08;--pushFace:linear-gradient(180deg,#FFF9DE 0%,#FDEBB0 10%,#F2CA66 30%,#CC9636 44%,#8C5C12 50%,#A6721F 56%,#EBC15A 72%,#FCE6A6 88%,#FFF8D8 100%)}
.fxs .push.au{box-shadow:inset 0 2px 0 rgba(255,255,255,.95),inset 0 -5px 8px rgba(110,70,10,.35),0 0 0 2.5px #FFF8DA,0 0 0 5px #A8741E,0 0 0 8.5px #FCE3A0,0 0 0 10.5px #5A3A08,
  0 8px 0 10.5px #D9A43A,0 10px 0 10.5px #5E3E0A,0 0 26px 14px rgba(255,228,150,.6),0 0 64px 26px rgba(255,185,50,.38),0 22px 34px rgba(0,0,0,.45)}
.fxs .push.au span{color:transparent;text-shadow:none}
.fxs .push.au::after{border-color:rgba(255,226,130,.95)}
.fxs .au .auf{position:absolute;left:0;top:0;width:200px;height:100px;border-radius:26px;overflow:hidden;pointer-events:none;font-style:normal}
.fxs .au .auf svg{display:block;width:200px;height:100px}
.fxs .au .aud{position:absolute;left:-40px;top:-30px;width:280px;height:160px;pointer-events:none;z-index:3;font-style:normal}
.fxs .au .aud svg{display:block;width:280px;height:160px;overflow:visible}
.fxs .au .aush{transform-box:view-box;transform-origin:0 0;animation:fxauShine 1.8s ease-in-out infinite}
.fxs .au .aush.b{animation-delay:.16s}
@keyframes fxauShine{0%{transform:translateX(0)}55%,100%{transform:translateX(330px)}}
.fxs .au .augl{opacity:0;animation:fxauGl 1.6s ease-in-out infinite}
@keyframes fxauGl{0%,50%,100%{opacity:0;transform:scale(.2) rotate(0deg)}64%{opacity:1;transform:scale(1.15) rotate(45deg)}80%{opacity:.25;transform:scale(.5) rotate(80deg)}}
.fxs .au .aurl{animation:fxauRim 1.3s linear infinite}
